const char *dav1d_version(void);

/**
 * Get the `dav1d` library C API version.
 *
 * Return a value in the format `0x00XXYYZZ`, where `XX` is the major version,
 * `YY` the minor version, and `ZZ` the patch version.
 */
unsigned int dav1d_version_api(void);

/**
 * # Safety
 *
 * * `s` must be valid to [`ptr::write`] to.
 *   The former contents of `s` are not [`drop`]ped and it may be uninitialized.
 */
void dav1d_default_settings(struct Dav1dSettings *s);

/**
 * # Safety
 *
 * * `s`, if [`NonNull`], must valid to [`ptr::read`] from.
 */
Dav1dResult dav1d_get_frame_delay(struct Dav1dSettings *s);

/**
 * # Safety
 *
 * * `c_out`, if [`NonNull`], is valid to [`ptr::write`] to.
 * * `s`, if [`NonNull`], is valid to [`ptr::read`] from.
 */
Dav1dResult dav1d_open(struct Option_Dav1dContext *c_out, struct Dav1dSettings *s);

/**
 * # Safety
 *
 * * `out`, if [`NonNull`], is valid to [`ptr::write`] to.
 * * `ptr`, if [`NonNull`], is the start of a `&[u8]` slice of length `sz`.
 */
Dav1dResult dav1d_parse_sequence_header(struct Dav1dSequenceHeader *out, uint8_t *ptr, size_t sz);

/**
 * # Safety
 *
 * * `c`, if [`NonNull`], must be from [`dav1d_open`] and not be passed to [`dav1d_close`] yet.
 * * `r#in`, if [`NonNull`], must be valid to [`ptr::read`] from and [`ptr::write`] to.
 */
Dav1dResult dav1d_send_data(struct Option_Dav1dContext c, struct Dav1dData *in);

/**
 * # Safety
 *
 * * `c`, if [`NonNull`], must be from [`dav1d_open`] and not be passed to [`dav1d_close`] yet.
 * * `out`, if [`NonNull`], must be valid to [`ptr::write`] to.
 */
Dav1dResult dav1d_get_picture(struct Option_Dav1dContext c, struct Dav1dPicture *out);

/**
 * # Safety
 *
 * * `c`, if [`NonNull`], must be from [`dav1d_open`] and not be passed to [`dav1d_close`] yet.
 * * `out`, if [`NonNull`], must be valid to [`ptr::write`] to.
 * * `r#in`, if [`NonNull`], must be valid to [`ptr::read`] from.
 */
Dav1dResult dav1d_apply_grain(struct Option_Dav1dContext c,
                              struct Dav1dPicture *out,
                              struct Dav1dPicture *in);

/**
 * # Safety
 *
 * * `c` must be from [`dav1d_open`] and not be passed to [`dav1d_close`] yet.
 */
void dav1d_flush(Dav1dContext c);

/**
 * # Safety
 *
 * * `c_out`, if [`NonNull`], must be safe to [`ptr::read`] from and [`ptr::write`] to.
 *   The `Dav1dContext` pointed to by `c_out` must be from [`dav1d_open`].
 */
void dav1d_close(struct Option_Dav1dContext *c_out);

/**
 * # Safety
 *
 * * `c`, if [`NonNull`], must be from [`dav1d_open`] and not be passed to [`dav1d_close`] yet.
 * * `flags`, if [`NonNull`], must be valid to [`ptr::write`] to.
 */
Dav1dResult dav1d_get_event_flags(struct Option_Dav1dContext c, Dav1dEventFlags *flags);

/**
 * # Safety
 *
 * * `c`, if [`NonNull`], must be from [`dav1d_open`] and not be passed to [`dav1d_close`] yet.
 * * `out`, if [`NonNull`], is valid to [`ptr::write`] to.
 */
Dav1dResult dav1d_get_decode_error_data_props(struct Option_Dav1dContext c,
                                              struct Dav1dDataProps *out);

/**
 * # Safety
 *
 * * `p`, if [`NonNull`], must be valid to [`ptr::read`] from and [`ptr::write`] to.
 */
void dav1d_picture_unref(struct Dav1dPicture *p);

/**
 * # Safety
 *
 * * `buf`, if [`NonNull`], is valid to [`ptr::write`] to.
 *   After this call, `buf.data` will be an allocated slice of length `sz`.
 */
uint8_t *dav1d_data_create(struct Dav1dData *buf, size_t sz);

/**
 * # Safety
 *
 * * `buf`, if [`NonNull`], is valid to [`ptr::write`] to.
 * * `ptr`, if [`NonNull`], is the start of a `&[u8]` slice of length `sz`.
 * * `ptr`'s slice must be valid to dereference until `free_callback` is called on it, which must deallocate it.
 */
Dav1dResult dav1d_data_wrap(struct Dav1dData *buf,
                            uint8_t *ptr,
                            size_t sz,
                            struct Option_FnFree free_callback,
                            struct Option_SendSyncNonNull_c_void user_data);

/**
 * # Safety
 *
 * * `buf`, if [`NonNull`], is valid to [`ptr::read`] from and [`ptr::write`] to.
 * * `user_data`, if [`NonNull`], is valid to dereference until `free_callback` is called on it, which must deallocate it.
 */
Dav1dResult dav1d_data_wrap_user_data(struct Dav1dData *buf,
                                      uint8_t *user_data,
                                      struct Option_FnFree free_callback,
                                      struct Option_SendSyncNonNull_c_void cookie);

/**
 * # Safety
 *
 * * `buf`, if [`NonNull`], is safe to [`ptr::read`] from and [`ptr::write`] from.
 */
void dav1d_data_unref(struct Dav1dData *buf);

/**
 * # Safety
 *
 * * `props`, if [`NonNull`], is safe to [`ptr::read`] from and [`ptr::write`] from.
 */
void dav1d_data_props_unref(struct Dav1dDataProps *props);

void dav1d_set_cpu_flags_mask(unsigned int mask);

